// ── Doctored flags for Flag Forgery ─────────────────────────────────────────
// Each entry is a real country's flag with exactly one detail quietly wrong.
// The SVGs in /public/fakes are edited copies of the self-hosted /public/flags
// originals, so they render pixel-identical in style to the genuine article —
// nothing about image quality gives them away. Most are generated by
// scripts/flags/fakes.mjs; each must stay a 640×480 SVG like the real art.
// Spot the Error deals the ones with `spot` too: you tap where the mistake is.

export interface FakeFlag {
  /** ISO code of the country being forged (never shown as a real card in the same round). */
  code: string
  name: string
  /** Doctored SVG under /fakes/. */
  src: string
  /** Terse in-round toast shown right after the swipe. */
  short: string
  /** Full explanation for the end-of-round recap. */
  reason: string
  /** Spot the Error: where the doctored detail is, so a tap there counts.
   *  Left out when the edit covers too much of the flag to point at (two bands
   *  swapped, stripes turned the other way, every triangle recoloured). */
  spot?: SpotInfo
}

/** What kind of mistake a doctored flag has. */
export type ErrorKind = "colour" | "count" | "position" | "turned" | "mirrored" | "missing" | "shape" | "swapped"

/** A region of a flag in the artwork's 640×480 viewBox (every file in
 *  public/flags and public/fakes uses it): a box, or the ellipse inside it. */
export interface HitBox { x: number; y: number; w: number; h: number; round?: boolean }

export interface SpotInfo {
  kind: ErrorKind
  /** 1 = easy (a big, plain change) … 3 = hard (a small detail). */
  level: 1 | 2 | 3
  /** Everywhere the fake differs from the real flag: the detail where it is
   *  now and, when it moved, where it should be. Checked against a pixel diff
   *  of the two SVGs when a fake is added. */
  hits: HitBox[]
}

